insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values
  ('bcaa1678-7f9f-51ed-bd04-825a7f3eec4d', 'Forania Nossa Senhora da Vitória. Horários da página da paróquia e das páginas das capelas no site da arquidiocese. 2 capelas/comunidades na página (2 com horário). Sé metropolitana; a igreja é a Catedral da Sé (Praça Dom Pedro II). Fora do formato: Todo dia 13, às 12h: missa votiva a Nossa Senhora de Fátima.; Todo dia 5, às 12h. (em honra a são Benedito). Ponto no mapa aproximado: centro da cidade.', '{"https://arquislz.org.br/paroquia/?paroquiaid=1","https://arquislz.org.br/capela/?capelaid=1","https://arquislz.org.br/capela/?capelaid=2"}', 'alta'),
  ('260f0555-c12a-5a67-9949-eb9afd1b9511', 'Forania Nossa Senhora da Vitória. Horários da página da paróquia e das páginas das capelas no site da arquidiocese. Igreja e convento do Carmo (Centro Histórico). A arquidiocese a lista entre as unidades da forania como "Igreja Nossa Senhora do Carmo", sem paróquia; o GCatholic a dá como santuário, daí a categoria. Fora do formato: Todo dia 16, às 12h: missa votiva a Nossa Senhora do Carmo.', '{"https://arquislz.org.br/paroquia/?paroquiaid=2"}', 'alta'),
  ('a97d86d3-7192-58b7-8769-a902e3dd918f', 'Forania Nossa Senhora da Vitória. Horários da página da paróquia e das páginas das capelas no site da arquidiocese. 2 capelas/comunidades na página (2 com horário). A matriz está interditada para reforma; as missas estão na Igreja de Sant''Ana. A Igreja de Santo Antônio (Centro), que a arquidiocese lista também como unidade própria, é capela desta paróquia: entrou aqui, com os horários e contatos da página própria dela. Fora do formato: Matriz interditada para reforma: missas e atividades transferidas para a Igreja de Sant''Ana (Rua de Santana).; Recebe as missas e atividades da matriz de São João Batista, em reforma. Missas votivas: todo dia 13 às 12h (Nossa Senhora de Fátima, com terço às 11h), todo dia 18 às 17h (Mãe Peregrina; adoração e terço a partir das 16h; no domingo, às 8h) e todo dia 29 às 12h (São Miguel Arcanjo). Quinta às 12h: missa da saúde. Ponto no mapa aproximado: centro da cidade.', '{"https://arquislz.org.br/paroquia/?paroquiaid=3","https://arquislz.org.br/capela/?capelaid=4","https://arquislz.org.br/capela/?capelaid=5"}', 'alta'),
  ('90a44bb9-01f1-5bd0-b497-b4ecef0376bc', 'Forania Nossa Senhora da Vitória. Horários da página da paróquia e das páginas das capelas no site da arquidiocese. 3 capelas/comunidades na página (3 com horário). Ponto no mapa aproximado: centro da cidade.', '{"https://arquislz.org.br/paroquia/?paroquiaid=5","https://arquislz.org.br/capela/?capelaid=6","https://arquislz.org.br/capela/?capelaid=7","https://arquislz.org.br/capela/?capelaid=8"}', 'alta'),
  ('04aa0359-76ee-5ad2-b8b9-f8207234f58c', 'Forania Nossa Senhora da Vitória. Horários da página da paróquia e das páginas das capelas no site da arquidiocese. 3 capelas/comunidades na página (3 com horário). Fora do formato: Todo dia 13, às 12h: missa votiva. Feriados santos, missa às 8h. Ponto no mapa aproximado: centro da cidade.', '{"https://arquislz.org.br/paroquia/?paroquiaid=6","https://arquislz.org.br/capela/?capelaid=9","https://arquislz.org.br/capela/?capelaid=10","https://arquislz.org.br/capela/?capelaid=11"}', 'alta'),
  ('535bdbb2-20c9-5902-a610-2ddac3a3a41c', 'Forania Anjo da Guarda. Horários da página da paróquia e das páginas das capelas no site da arquidiocese. 8 capelas/comunidades na página (8 com horário). Fora do formato: Todo dia 13, às 12h: missa votiva. Ponto no mapa aproximado: centro da cidade.', '{"https://arquislz.org.br/paroquia/?paroquiaid=7","https://arquislz.org.br/capela/?capelaid=12","https://arquislz.org.br/capela/?capelaid=13","https://arquislz.org.br/capela/?capelaid=14","https://arquislz.org.br/capela/?capelaid=863","https://arquislz.org.br/capela/?capelaid=864","https://arquislz.org.br/capela/?capelaid=865","https://arquislz.org.br/capela/?capelaid=866","https://arquislz.org.br/capela/?capelaid=867"}', 'alta'),
  ('077d9fed-be18-51a2-964b-3b3a4b66ea9f', 'Forania Anjo da Guarda. Horários da página da paróquia e das páginas das capelas no site da arquidiocese. 14 capelas/comunidades na página (14 com horário). Ponto no mapa aproximado: centro da cidade.', '{"https://arquislz.org.br/paroquia/?paroquiaid=8","https://arquislz.org.br/capela/?capelaid=15","https://arquislz.org.br/capela/?capelaid=16","https://arquislz.org.br/capela/?capelaid=17","https://arquislz.org.br/capela/?capelaid=18","https://arquislz.org.br/capela/?capelaid=19","https://arquislz.org.br/capela/?capelaid=20","https://arquislz.org.br/capela/?capelaid=21","https://arquislz.org.br/capela/?capelaid=22","https://arquislz.org.br/capela/?capelaid=23","https://arquislz.org.br/capela/?capelaid=24","https://arquislz.org.br/capela/?capelaid=25","https://arquislz.org.br/capela/?capelaid=26","https://arquislz.org.br/capela/?capelaid=27","https://arquislz.org.br/capela/?capelaid=868"}', 'alta'),
  ('3eae48db-c66a-573b-9756-b70257ba6140', 'Forania São Luís Rei de França. Horários da página da paróquia e das páginas das capelas no site da arquidiocese. Fora do formato: Todo dia 12, às 12h: missa votiva. Ponto no mapa aproximado: centro da cidade.', '{"https://arquislz.org.br/paroquia/?paroquiaid=9"}', 'alta'),
  ('9e9722da-ee4a-55e5-87b9-5587c44c588f', 'Forania São Luís Rei de França. Horários da página da paróquia e das páginas das capelas no site da arquidiocese. 3 capelas/comunidades na página (3 com horário).', '{"https://arquislz.org.br/paroquia/?paroquiaid=10","https://arquislz.org.br/capela/?capelaid=28","https://arquislz.org.br/capela/?capelaid=29","https://arquislz.org.br/capela/?capelaid=30"}', 'alta'),
  ('3a8bd196-7af9-579e-ba46-1a7b9b27bdf4', 'Forania São Luís Rei de França. Horários da página da paróquia e das páginas das capelas no site da arquidiocese. 5 capelas/comunidades na página (5 com horário). Fora do formato: Todo dia 13, às 12h, exceto no domingo: missa votiva a Nossa Senhora de Fátima. Missa da saúde no 3º sábado do mês (sem hora publicada).', '{"https://arquislz.org.br/paroquia/?paroquiaid=11","https://arquislz.org.br/capela/?capelaid=31","https://arquislz.org.br/capela/?capelaid=32","https://arquislz.org.br/capela/?capelaid=33","https://arquislz.org.br/capela/?capelaid=34","https://arquislz.org.br/capela/?capelaid=35"}', 'alta'),
  ('77fddb19-fdac-55db-8a4e-e8b4e35ee8cf', 'Forania Nossa Senhora da Conceição. Horários da página da paróquia e das páginas das capelas no site da arquidiocese. 5 capelas/comunidades na página (3 com horário). Fora do formato: Todo dia 13, às 19h. (Em honra a Santa Luzia).; Todo dia 19, às 12h. (Em honra a Santo Expedito).', '{"https://arquislz.org.br/paroquia/?paroquiaid=12","https://arquislz.org.br/capela/?capelaid=45","https://arquislz.org.br/capela/?capelaid=46","https://arquislz.org.br/capela/?capelaid=47"}', 'alta'),
